void mainImage( out vec4 o, vec2 U )
{
    vec2 R = iResolution.xy;
    float t = iTime;
    float n = 10.;
    vec2 u = (U-R/2.)/R.y;
    o = vec4(.4, 0., sin(t)*.4, 0.);
    for (int i = 0; i < 20; i++) {
        vec2 w = (u*=.94)/ (1. + .1 * (1. - u.y*.8));
        w.x -= t*.1;
        float e, s = .4-float(i)*.02;
        e = float(i)*.5+t*2.*fract(sin(dot((floor(w*n)+2.).xy, vec2(12.99,78.23))) * 43758.55);
        w -= vec2(sin(e)*.01,cos(e)*.01) ;
        if (length(fract(w*n)-.5) < s) {
            o = vec4(s, float(i)/20., sin(float(i)*0.2+t)*0.4, float(i)/20.);
        }
    }
}
